import java.util.*;

class Solution {
    public int fewestSquares(int n) {
        int[] best = new int[n + 1];
        for (int x = 1; x <= n; x++) {
            best[x] = x;                                  // worst case: all 1s
            for (int s = 1; s * s <= x; s++)
                best[x] = Math.min(best[x], best[x - s * s] + 1);   // last square is s*s
        }
        return best[n];
    }
}

