class Solution:
    def fewestSquares(self, n: int) -> int:
        sq = [i * i for i in range(1, int(n ** 0.5) + 1)]
        best = [0] + [inf] * n
        for x in range(1, n + 1):
            b = inf
            for s in sq:
                if s > x: break
                if best[x - s] < b: b = best[x - s]
            best[x] = b + 1
        return best[n]

