function fewestSquares(n) {
  const isSq = (x) => { const r = Math.floor(Math.sqrt(x)); return r * r === x; };
  if (isSq(n)) return 1;
  for (let a = 1; a * a <= n; a++) if (isSq(n - a * a)) return 2;
  let m = n; while (m % 4 === 0) m /= 4;
  if (m % 8 === 7) return 4;
  return 3;
}
